var currentApprovalId=null,statusLabels={pending:"label-warning",approved:"label-success",rejected:"label-danger",changes_requested:"label-info",expired:"label-default"};function statusBadge(e){return'<span class="label '+(statusLabels[e]||"label-default")+'">'+e+"</span>"}function resend(e){api.approvalId.resend(e).success((function(e){e.approvers_notified<e.approvers_total?errorFlash("Reminder recorded, but only "+e.approvers_notified+" of "+e.approvers_total+" approver(s) could be e-mailed. Check the sending profile configuration."):successFlash("Approval reminder resent"),load()})).error((function(){errorFlash("Error resending approval request")}))}function viewApproval(e){currentApprovalId=e,api.approvalId.get(e).success((function(e){$("#approvalModalLabel").text("Approval Request #"+e.id),$("#approvalStatus").html("Status: "+statusBadge(e.status)+"<br/>Requested: "+e.requested_at+(e.decided_at?"<br/>Decided: "+e.decided_at:"")),renderComments(e.comments||[]),$("#approvalModal").modal("show")}))}function renderComments(e){var a=$("#approvalComments");a.empty(),0!==e.length?e.forEach((function(e){a.append('<div style="margin-bottom:8px;"><strong>'+escapeHtml(e.author_type)+"</strong> - "+escapeHtml(e.created_at)+"<br/>"+escapeHtml(e.body)+"</div>")})):a.append('<p class="text-muted">No comments yet.</p>')}function addComment(){var e=$("#newComment").val();e&&api.approvalId.comment(currentApprovalId,e).success((function(){$("#newComment").val(""),viewApproval(currentApprovalId)}))}function exportEvidence(){$.ajax({url:"/api/approvals/"+currentApprovalId+"/export",method:"GET",beforeSend:function(e){e.setRequestHeader("Authorization","Bearer "+user.api_key)}}).done((function(e){var a=new Blob([JSON.stringify(e,null,2)],{type:"application/json"}),t=URL.createObjectURL(a),r=document.createElement("a");r.href=t,r.download="approval-"+currentApprovalId+"-evidence.json",r.click(),URL.revokeObjectURL(t)})).fail((function(){errorFlash("Error exporting evidence")}))}funct